  Definition oswin (lo SP ff : Z) (iv : Z * Z) : Prop :=
    (lo <= fst iv /\ snd iv <= SP) \/ (ff <= fst iv /\ snd iv <= ff + 64) \/ (sh ff <= fst iv /\ snd iv <= sh ff + 8).

  Lemma oswin_ok : forall LF LB ff fp lo SP iv, fresh_frame H LF 0 ff fp ->
    aceil <= lo -> SP <= 2 ^ 47 -> oswin lo SP ff iv ->
