  Lemma os_transport : forall LF LB s ff fp lo SP W m m',
    fresh_frame H LF 0 ff fp -> aceil <= lo -> SP <= 2 ^ 47 -> Forall (oswin lo SP ff) W ->
    munch W m m' -> wmono asegs m m' ->
    as_RFS H ((0, ff, fp) :: LF) m -> as_RHEAP H s LB m -> ACONST m ->
    as_RFS H ((0, ff, fp) :: LF) m' /\ as_RHEAP H s LB m' /\ ACONST m'.
Proof.
