Section OS.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.
  Hypothesis HH : asan_rt_hyps_bp H.

  Lemma os_fin : forall (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : as_St H) (LB : list block) (LF : list fframe) (lo : Z) (m mb : mem)
      (Rb : bvmap 5 word) (pcb : Z) (M' : mem) (ff fp res n : Z)
      (w5 w6 w7 w11 w12 w13 w14 w15 w16 w17 w28 w29 w30 w31 : word),
    bv_unsigned sp <= 2 ^ 47 -> aceil <= lo -> lo <= bv_unsigned sp - OS_STACK ->
    fresh_frame H LF 0 ff fp ->
    CatSim.msteps asegs (MS Rb F (Z_to_bv 64 pcb) fc None mb (seg_rom asegs))
      (MS (mkR ra sp gp tp w5 w6 w7 s0 s1 (Z_to_bv 64 res) w11 w12 w13 w14 w15 w16 w17 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11
               w28 w29 w30 w31) F (Z_to_bv 64 OS_RET) fc None M' (seg_rom asegs)) ->
    munch [(sh ff, sh ff + 8); (ff, ff + 8); (fp, fp + 1)] mb M' -> wmono asegs mb M' -> mem_inv asegs M' ->
    (forall lo' hi', stk asegs mb lo' hi' -> stk asegs M' lo' hi') -> mrd asegs M' (wa fp) = Some (b8 0) ->
    as_RFS H ((0, ff, fp) :: LF) mb -> as_RHEAP H s LB mb -> ACONST mb -> stk asegs mb lo (bv_unsigned sp) ->
    munch ((bv_unsigned sp - OS_STACK, bv_unsigned sp) ::
           [(as_FSB H, as_FSB H + AFS_FLAGS); (fp, fp + 1); (ff, ff + 64); (sh ff, sh ff + 8)]) m mb ->
    wmono asegs m mb ->
    cstrA res n ->
    evt asegs (opcode_string_post H ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB LF lo m)
      (MS Rb F (Z_to_bv 64 pcb) fc None mb (seg_rom asegs)).
Proof.
