  Theorem opcode_string_okA : opcode_string_stmtA H.
  Proof.
    unfold opcode_string_stmtA.
    intros ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
      F fc m s LB LF op lo Ha0 Hop Hstk Hlo Hlo2 Hsp16 Hsp47 HRFS HLF HRH Hinv Htp HAC Hrel.
    pose proof (rt_bp_base H HH) as HB.
    pose proof (rt_bp_ext H HH) as HX.
    destruct HX as [SM0 _].
    destruct aceil_facts as [[Hac1 Hac2] [Hac3 [Hac4 Hac5]]].
    assert (HOS : OS_STACK = 1184) by (unfold OS_STACK, AFS_STACK, TL_STACK; lia).
    eapply evt_cut.
    { apply (os_b1 ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m op lo);
        auto; lia. }
    intros ms1 HP1.
    destruct HP1 as (x5 & x6 & x7 & x11 & x12 & x13 & x14 & x15 & x16 & x17 & x28 & x29 & x30 & x31 & m1 &
                     -> & HMU1 & HWM1 & HINV1 & HSTK1 & HRW1).
    assert (HX2 : as_FSB H + AFS_SIZE <= aceil)
      by (pose proof (ah_RFS_range H HB _ _ HRFS) as [(_ & X & _) _]; exact X).
    assert (HX1 : aceil <= bv_unsigned sp - 64) by lia.
    pose proof (stack_window_ok H LB LF (bv_unsigned sp - 64) (bv_unsigned sp) HX1 HX2) as (W1a & W1b & W1c).
    assert (HRF1 : as_RFS H LF m1)
      by (eapply (ah_RFS_frame H HB); [exact HRFS | exact HMU1 | exact HWM1 | apply Forall_cons; [exact W1b | apply Forall_nil]]).
    assert (HRH1 : as_RHEAP H s LB m1)
      by (eapply (ah_RHEAP_frame H HB); [exact HRH | exact HMU1 | exact HWM1 | apply Forall_cons; [exact W1a | apply Forall_nil]]).
    assert (HAC1 : ACONST m1)
      by (eapply ACONST_frame; [exact HAC | exact HMU1 | exact HWM1 | apply Forall_cons; [exact W1c | apply Forall_nil]]).
    pose proof (Z.mod_pos_bound (bv_unsigned sp) 32 ltac:(lia)) as HSPm.
    eapply evt_cut.
    { eapply (SM0 _ (Z_to_bv 64 (bv_unsigned sp - 64 - bv_unsigned sp mod 32))) with (LF := LF) (lo := lo);
        [exact HRF1 | exact HLF
        | rewrite HLib.u64_of_Z by lia;
          exact (proj1 (stk_split asegs m1 lo (bv_unsigned sp - 64 - bv_unsigned sp mod 32) (bv_unsigned sp) HSTK1 ltac:(lia)))
        | exact Hlo | rewrite HLib.u64_of_Z by lia; unfold AFS_STACK; lia | exact HINV1 | exact Htp | exact HAC1
        | exact (ah_thr H HB _ _ _ HRH1)]. }
    intros ms2 HP2.
    destruct HP2 as (u0 & u1 & u2 & b1 & b2 & b3 & b4 & b5 & b6 & b7 & u3 & u4 & u5 & u6 & m2 & ff & fp & j1 & j2
                     & -> & HMU2 & HWM2 & HINV2 & HSTK2 & HRF2 & HCF2 & HSF2 & HFP2 & HAC2).
    rewrite HLib.u64_of_Z in HMU2, HSTK2 by lia. unfold AFS_STACK in HMU2.
    rewrite (ret_pc_even OS_SM_RET ltac:(unfold OS_SM_RET; lia) eq_refl).
    pose proof (fresh_of_RFS H HB LF 0 ff fp m2 HRF2) as FFR.
    pose proof FFR as FFR'.
    apply (osframe_facts H) in FFR' as (G1 & G2 & G3 & G4 & G5 & G6 & G7 & G8 & G9 & G10 & G11 & G12 & G13 & G14 & G15 & G16 & G17 & G18).
    change (fsz 0) with 64 in HMU2, HCF2. change (fshn 0) with 8 in HMU2, HSF2.
    change (Z.to_nat (64 - 40)) with 24%nat in HCF2.
    assert (HSTK2f : stk asegs m2 lo (bv_unsigned sp)).
    { destruct (stk_split asegs m1 lo (bv_unsigned sp - 64 - bv_unsigned sp mod 32) (bv_unsigned sp) HSTK1 ltac:(lia))
        as [_ STu].
      assert (STu2 : stk asegs m2 (bv_unsigned sp - 64 - bv_unsigned sp mod 32) (bv_unsigned sp))
        by (eapply stk_transport_disjoint; [exact STu | exact HMU2 | exact HWM2 | cbn; unfold AFS_FLAGS, AFS_SIZE in *; lia]).
      exact (stk_merge asegs m2 lo _ _ HSTK2 STu2 ltac:(lia)). }
    assert (HRW2 : rw_cells asegs m2 (bv_unsigned sp - 64)
                     [C8 (Z_to_bv 64 0); C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra]).
    { eapply rw_cells_transport; [exact HRW1 | exact HMU2 | exact HWM2 |].
      cbn; unfold AFS_FLAGS, AFS_SIZE in *; lia. }
    assert (WF2 : wr_at asegs m2 ff 64) by (eapply rw_cells_wr_at; [exact HCF2 | cbn; lia]).
    assert (WS2 : wr_at asegs m2 (sh ff) 8).
    { pose proof HSF2 as HSF2'. destruct HSF2' as (_ & _ & (_ & W)).
      match type of W with
      | wr_at _ _ _ (Z.of_nat (length ?l)) =>
          assert (L : Z.of_nat (length l) = 8) by reflexivity; rewrite L in W; exact W
      end. }
    assert (CFP2 : rw_cells asegs m2 (ff + 56) [C8 (Z_to_bv 64 fp)]).
    { pose proof HCF2 as HCF2'.
      apply (rw_cells_app asegs m2 ff [CB 24 j1; C8 (Z_to_bv 64 (bv_unsigned sp - 64 - bv_unsigned sp mod 32)); CB 24 j2]
               [C8 (Z_to_bv 64 fp)]) in HCF2' as [_ CFb].
      cbn [cells_size csize] in CFb. change (Z.of_nat (24 + (8 + (24 + 0)))) with 56 in CFb. exact CFb. }
    assert (HRR2 : relro0 m2).
    { intros i Hi. rewrite (HMU2 (Z_to_bv 64 i)); [rewrite (HMU1 (Z_to_bv 64 i)); [apply Hrel; exact Hi|]|].
      all: rewrite HLib.u64_of_Z by lia; cbn [outside]; unfold AFS_FLAGS, AFS_SIZE in *; lia. }
    assert (HS1m : (bv_unsigned sp - 64 - bv_unsigned sp mod 32) mod 32 = 0).
    { replace (bv_unsigned sp - 64 - bv_unsigned sp mod 32) with ((bv_unsigned sp / 32 - 2) * 32)
        by (pose proof (Z.div_mod (bv_unsigned sp) 32 ltac:(lia)); lia).
      apply Z.mod_mul; lia. }
    pose proof (os_b2 u0 u1 u2 b1 b2 b3 b4 b5 b6 b7 u3 u4 u5 u6 gp tp s2 s5 s6 s7 s8 s9 s10 s11 F fc m2 (seg_rom asegs)
                ff (bv_unsigned sp) (bv_unsigned sp - 64 - bv_unsigned sp mod 32) op lo G3) as B2.
    specialize (B2 ltac:(lia)).
    specialize (B2 ltac:(lia)).
    specialize (B2 ltac:(lia)).
    specialize (B2 Hop HS1m).
    specialize (B2 ltac:(lia)).
    specialize (B2 ltac:(lia)).
    specialize (B2 Hsp47 WF2 WS2 HSTK2f ltac:(lia) HRR2 HINV2).
    destruct B2
      as (R3 & m3 & RUN3 & E1 & E2 & E3 & E4 & E8 & E9 & E10 & E11 & E18 & E19 & E20 & E21 & E22 & E23 & E24 & E25
          & E26 & E27 & HMU3 & HWM3 & HINV3 & HSTK3 & HCS3).
    assert (HRH2 : as_RHEAP H s LB m2).
    { eapply (ah_RHEAP_frame H HB); [exact HRH1 | exact HMU2 | exact HWM2 |].
      apply Forall_cons; [unfold aclient_write_ok; cbn [fst snd]; left; lia|].
      apply Forall_cons; [unfold aclient_write_ok; cbn [fst snd]; do 4 right; left; unfold AFS_FLAGS, AFS_SIZE in *; lia|].
      apply Forall_cons; [unfold aclient_write_ok; cbn [fst snd]; do 4 right; left; unfold AFS_SIZE in *; lia|].
      apply Forall_cons; [unfold aclient_write_ok; cbn [fst snd]; do 4 right; left; lia|].
      apply Forall_cons; [unfold aclient_write_ok; cbn [fst snd]; do 5 right; left; lia|].
      apply Forall_nil. }
    assert (T3 : as_RFS H ((0, ff, fp) :: LF) m3 /\ as_RHEAP H s LB m3 /\ ACONST m3).
    { eapply (os_transport H HB LF LB s ff fp lo (bv_unsigned sp));
        [exact FFR | exact Hlo | exact Hsp47 | | exact HMU3 | exact HWM3 | exact HRF2 | exact HRH2 | exact HAC2].
      apply Forall_cons; [unfold oswin; cbn [fst snd]; left; lia|].
      apply Forall_cons; [unfold oswin; cbn [fst snd]; right; left; lia|].
      apply Forall_cons; [unfold oswin; cbn [fst snd]; right; right; lia|].
      apply Forall_nil. }
    destruct T3 as (HRF3 & HRH3 & HAC3).
    eapply evt_of_msteps; [exact RUN3|].
    pose proof (msteps_full asegs _ _ RUN3 (rfull_mkR _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _)) as HF3.
    cbn [ms_regs] in HF3.
    change (rfull R3) in HF3.
    assert (HRWt : rw_cells asegs m2 (bv_unsigned sp - 64 + 8) [C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra]).
    { pose proof HRW2 as HRW2'.
      apply (rw_cells_app asegs m2 (bv_unsigned sp - 64) [C8 (Z_to_bv 64 0)]
               [C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra]) in HRW2' as [_ X].
      exact X. }
    assert (HRW3 : rw_cells asegs m3 (bv_unsigned sp - 64 + 8) [C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra])
      by (eapply rw_cells_transport; [exact HRWt | exact HMU3 | exact HWM3 | cbn; unfold AFS_FLAGS, AFS_SIZE in *; lia]).
    assert (CFP3 : rw_cells asegs m3 (ff + 56) [C8 (Z_to_bv 64 fp)])
      by (eapply rw_cells_transport; [exact CFP2 | exact HMU3 | exact HWM3 | cbn; unfold AFS_FLAGS, AFS_SIZE in *; lia]).
    assert (HFP3 : rw_cells asegs m3 fp [C1 (b8 1)])
      by (eapply rw_cells_transport; [exact HFP2 | exact HMU3 | exact HWM3 | cbn; unfold AFS_FLAGS, AFS_SIZE in *; lia]).
    rewrite (MS_full_eq R3 F (Z_to_bv 64 AT_LOOKUP_OPCODE) fc m3 (seg_rom asegs) HF3).
    rewrite E1, E2, E3, E4, E8, E9, E10, E11, E18, E19, E20, E21, E22, E23, E24, E25, E26, E27.
    assert (Hsh4 : forall x, ff + 32 <= x < ff + 40 -> sh x = sh ff + 4).
    { intros x Hx. pose proof (Z.div_mod ff 64 ltac:(lia)) as Hq. rewrite G3 in Hq. unfold sh.
      rewrite <- (Z.div_unique x 8 (8 * (ff / 64) + 4) (x - ff - 32)) by lia.
      rewrite <- (Z.div_unique ff 8 (8 * (ff / 64)) 0) by lia.
      ring. }
    assert (TLC : tl_cell m3 (bv_unsigned sp - 64 - bv_unsigned sp mod 32) (ff + 32) 8).
    { unfold tl_cell. split; [|split; [|split; [|split]]].
      - exact (os_wr_at_sub m3 ff 64 (ff + 32) 8 (LbB_Own.wr_at_wmono m2 m3 ff 64 WF2 HWM3)
                 ltac:(lia) ltac:(lia) ltac:(lia)).
      - split; [lia|]. split; [unfold AAPP_HI; lia|].
        intros x Hx. exists 0. split; [lia|]. split; [|unfold byte_ok; left; reflexivity].
        rewrite (Hsh4 x ltac:(lia)). exact (BsWalk.rw_cells_C1_mrd asegs m3 (sh ff + 4) (b8 0) [] HCS3).
      - exact (aconst_ok_app (as_FSB H) AFS_SIZE (ff + 32) (ff + 32 + 8) G10 ltac:(lia) ltac:(lia)).
      - left. unfold TL_STACK. lia.
      - destruct G17 as [G17 | G17]; [left | right]; split; lia. }
    pose proof lookup_opcode_okA as LK.
    unfold lookup_opcode_stmtA, lookup_shapeA, tleaf in LK.
    eapply evt_cut.
    { eapply (LK (op, 0, ff + 32)) with (lo := lo).
      - rewrite HLib.u64_of_Z by lia.
        exact (proj1 (stk_split asegs m3 lo (bv_unsigned sp - 64 - bv_unsigned sp mod 32) (bv_unsigned sp) HSTK3 ltac:(lia))).
      - exact Hlo.
      - rewrite HLib.u64_of_Z by lia. unfold TL_STACK. lia.
      - rewrite HLib.u64_of_Z by lia.
        pose proof (Z.div_mod (bv_unsigned sp - 64 - bv_unsigned sp mod 32) 32 ltac:(lia)) as Hq.
        rewrite HS1m, Z.add_0_r in Hq. rewrite Hq.
        replace (32 * ((bv_unsigned sp - 64 - bv_unsigned sp mod 32) / 32))
          with ((bv_unsigned sp - 64 - bv_unsigned sp mod 32) / 32 * 2 * 16) by ring.
        apply Z.mod_mul. lia.
      - rewrite HLib.u64_of_Z by lia. pose proof (Z.mod_pos_bound (bv_unsigned sp) 32 ltac:(lia)). lia.
      - exact HINV3.
      - exact HAC3.
      - cbv beta iota. rewrite HLib.u64_of_Z by lia.
        split; [exact Hop|]. split; [reflexivity|]. split; [intros _; reflexivity|].
        split; [intros X; discriminate X|]. split; [|exact TLC].
        pose proof (Z.div_mod ff 64 ltac:(lia)) as Hq. rewrite G3, Z.add_0_r in Hq.
        replace (ff + 32) with ((ff / 64 * 8 + 4) * 8) by lia.
        apply Z.mod_mul. lia. }
    intros ms4 HP4.
    destruct HP4 as (w0 & w1 & w2 & r0 & r1 & w3 & w4 & w5 & w6 & w7 & w8 & w9 & w10 & w11 & w12 & m4
                     & -> & HMU4 & HWM4 & HINV4 & HSTK4 & HAC4 & HQ4).
    cbv beta iota in HQ4.
    destruct HQ4 as (r & Hr0 & Hrr & Hfound & Hdesc & Hnd).
    rewrite HLib.u64_of_Z in HMU4, HSTK4 by lia.
    assert (W34 : Forall (oswin lo (bv_unsigned sp) ff)
                    [(bv_unsigned sp - 64 - bv_unsigned sp mod 32 - TL_STACK, bv_unsigned sp - 64 - bv_unsigned sp mod 32);
                     (ff + 32, ff + 32 + 8)]).
    { apply Forall_cons; [unfold oswin, TL_STACK; cbn [fst snd]; left; lia|].
      apply Forall_cons; [unfold oswin; cbn [fst snd]; right; left; lia|].
      apply Forall_nil. }
    assert (T4 : as_RFS H ((0, ff, fp) :: LF) m4 /\ as_RHEAP H s LB m4 /\ ACONST m4)
      by (eapply (os_transport H HB LF LB s ff fp lo (bv_unsigned sp));
          [exact FFR | exact Hlo | exact Hsp47 | exact W34 | exact HMU4 | exact HWM4 | exact HRF3 | exact HRH3 | exact HAC3]).
    destruct T4 as (HRF4 & HRH4 & _).
    assert (HRW4 : rw_cells asegs m4 (bv_unsigned sp - 56) [C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra]).
    { replace (bv_unsigned sp - 56) with (bv_unsigned sp - 64 + 8) by lia.
      eapply rw_cells_transport; [exact HRW3 | exact HMU4 | exact HWM4 | cbn; unfold TL_STACK; lia]. }
    assert (CFP4 : rw_cells asegs m4 (ff + 56) [C8 (Z_to_bv 64 fp)])
      by (eapply rw_cells_transport; [exact CFP3 | exact HMU4 | exact HWM4 | cbn; unfold TL_STACK; lia]).
    assert (STK4u : stk asegs m4 (bv_unsigned sp - 64 - bv_unsigned sp mod 32) (bv_unsigned sp))
      by (eapply stk_transport_disjoint;
          [exact (proj2 (stk_split asegs m3 lo (bv_unsigned sp - 64 - bv_unsigned sp mod 32) (bv_unsigned sp) HSTK3 ltac:(lia)))
          | exact HMU4 | exact HWM4 | cbn; unfold TL_STACK; lia]).
    assert (STK4 : stk asegs m4 lo (bv_unsigned sp)) by exact (stk_merge asegs m4 lo _ _ HSTK4 STK4u ltac:(lia)).
    assert (WM4 : wmono asegs m m4)
      by exact (wmono_trans asegs m m1 m4 HWM1 (wmono_trans asegs m1 m2 m4 HWM2 (wmono_trans asegs m2 m3 m4 HWM3 HWM4))).
    assert (MU4 : munch ((bv_unsigned sp - OS_STACK, bv_unsigned sp) ::
                         [(as_FSB H, as_FSB H + AFS_FLAGS); (fp, fp + 1); (ff, ff + 64); (sh ff, sh ff + 8)]) m m4).
    { apply (munch_trans _ m m3 m4); [apply (munch_trans _ m m2 m3); [apply (munch_trans _ m m1 m2)|]|].
      all: eapply munch_weaken; [|eassumption]; intros xx Hxx; cbn in Hxx |- *; clear - Hxx HSPm HOS;
        unfold TL_STACK in *; lia. }
    assert (WF4 : wr_at asegs m4 ff 8)
      by exact (os_wr_at_sub m4 ff 64 ff 8 (LbB_Own.wr_at_wmono m2 m4 ff 64 WF2 (wmono_trans asegs m2 m3 m4 HWM3 HWM4))
                  ltac:(lia) ltac:(lia) ltac:(lia)).
    assert (WS4 : wr_at asegs m4 (sh ff) 8)
      by exact (LbB_Own.wr_at_wmono m2 m4 (sh ff) 8 WS2 (wmono_trans asegs m2 m3 m4 HWM3 HWM4)).
    assert (WP4 : wr_at asegs m4 fp 1)
      by exact (LbB_Own.wr_at_wmono m3 m4 fp 1 (rw_cells_wr_at asegs m3 fp [C1 (b8 1)] 1 HFP3 ltac:(cbn; lia)) HWM4).
    destruct (Z.eq_dec r 0) as [Hr | Hr].
    - subst r. subst r0.
      destruct (Hdesc eq_refl) as (d & CD4 & HID).
      destruct (idescA_facts d op HID) as (ri & _ & _ & _ & Dlo & Dhi & D4 & _).
      rewrite (ret_pc_even OS_LO_RET ltac:(unfold OS_LO_RET; lia) eq_refl).
      destruct (os_b3f (Z_to_bv 64 OS_LO_RET) w0 w1 w2 r1 w3 w4 w5 w6 w7 w8 w9 w10 w11 w12 gp tp s6 s7 s8 s9 s10 s11
                  F fc m4 (seg_rom asegs) ff (bv_unsigned sp) (bv_unsigned sp - 64 - bv_unsigned sp mod 32) d
                  G3 ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) D4 CD4) as (R5 & RUN5 & ->).
      eapply evt_of_msteps; [exact RUN5|].
      pose proof idesc_name_okA as IN.
      unfold idesc_name_stmtA, tleaf in IN.
      eapply evt_cut.
      { eapply (IN (d, op)) with (lo := lo).
        - rewrite HLib.u64_of_Z by lia. exact HSTK4.
        - exact Hlo.
        - rewrite HLib.u64_of_Z by lia. unfold TL_STACK. lia.
        - rewrite HLib.u64_of_Z by lia.
          pose proof (Z.div_mod (bv_unsigned sp - 64 - bv_unsigned sp mod 32) 32 ltac:(lia)) as Hq.
          rewrite HS1m, Z.add_0_r in Hq. rewrite Hq.
          replace (32 * ((bv_unsigned sp - 64 - bv_unsigned sp mod 32) / 32))
            with ((bv_unsigned sp - 64 - bv_unsigned sp mod 32) / 32 * 2 * 16) by ring.
          apply Z.mod_mul. lia.
        - rewrite HLib.u64_of_Z by lia. lia.
        - exact HINV4.
        - exact HAC4.
        - cbv beta iota. split; [exact HID | reflexivity]. }
      intros ms5 HP5.
      destruct HP5 as (y0 & y1 & y2 & ya0 & ya1 & ya2 & ya3 & ya4 & ya5 & ya6 & ya7 & y3 & y4 & y5 & y6 & m5
                       & -> & HMU5 & HWM5 & HINV5 & HSTK5 & HAC5 & HQ5).
      cbv beta iota in HMU5, HQ5.
      destruct HQ5 as (np & nn & Hcs & ->).
      rewrite HLib.u64_of_Z in HMU5, HSTK5 by lia.
      rewrite (ret_pc_even OS_NM_RET ltac:(unfold OS_NM_RET; lia) eq_refl).
      assert (HRW5 : rw_cells asegs m5 (bv_unsigned sp - 56) [C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra])
        by (eapply rw_cells_transport; [exact HRW4 | exact HMU5 | exact HWM5 | cbn; unfold TL_STACK; lia]).
      assert (CFP5 : rw_cells asegs m5 (ff + 56) [C8 (Z_to_bv 64 fp)])
        by (eapply rw_cells_transport; [exact CFP4 | exact HMU5 | exact HWM5 | cbn; unfold TL_STACK; lia]).
      assert (T5 : as_RFS H ((0, ff, fp) :: LF) m5 /\ as_RHEAP H s LB m5 /\ ACONST m5).
      { eapply (os_transport H HB LF LB s ff fp lo (bv_unsigned sp));
          [exact FFR | exact Hlo | exact Hsp47 | | exact HMU5 | exact HWM5 | exact HRF4 | exact HRH4 | exact HAC4].
        apply Forall_cons; [unfold oswin, TL_STACK; cbn [fst snd]; left; lia | apply Forall_nil]. }
      destruct T5 as (HRF5 & HRH5 & _).
      assert (STK5 : stk asegs m5 lo (bv_unsigned sp)).
      { eapply stk_merge; [exact HSTK5 | | lia].
        eapply stk_transport_disjoint; [exact STK4u | exact HMU5 | exact HWM5 | cbn; unfold TL_STACK; lia]. }
      assert (MU5 : munch ((bv_unsigned sp - OS_STACK, bv_unsigned sp) ::
                           [(as_FSB H, as_FSB H + AFS_FLAGS); (fp, fp + 1); (ff, ff + 64); (sh ff, sh ff + 8)]) m m5).
      { apply (munch_trans _ m m4 m5 MU4). eapply munch_weaken; [|exact HMU5].
        intros xx Hxx; cbn in Hxx |- *; clear - Hxx HSPm HOS; unfold TL_STACK in *; lia. }
      destruct (os_tail false (Z_to_bv 64 OS_NM_RET) y0 y1 y2 (Z_to_bv 64 np) ya1 ya2 ya3 ya4 ya5 ya6 ya7 y3 y4 y5 y6
                  ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m5 (seg_rom asegs)
                  ff fp (bv_unsigned sp) (bv_unsigned sp - 64 - bv_unsigned sp mod 32) np
                  eq_refl G3 ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia)
                  HRW5 CFP5 (LbB_Own.wr_at_wmono m4 m5 ff 8 WF4 HWM5) (LbB_Own.wr_at_wmono m4 m5 (sh ff) 8 WS4 HWM5)
                  (LbB_Own.wr_at_wmono m4 m5 fp 1 WP4 HWM5) HINV5)
        as (R6 & M6 & RUN6 & E6 & HMU6 & HWM6 & HINV6 & HSTK6 & HRD6).
      rewrite E6 in RUN6. rewrite !Z_to_bv_bv_unsigned in RUN6 |- *.
      eapply (os_fin ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB LF lo m m5 _ OS_NM_RET M6 ff fp np nn);
        [exact Hsp47 | exact Hlo | exact Hlo2 | exact FFR | exact RUN6 | exact HMU6 | exact HWM6 | exact HINV6
        | exact HSTK6 | exact HRD6 | exact HRF5 | exact HRH5 | exact HAC5 | exact STK5 | exact MU5
        | exact (wmono_trans asegs m m4 m5 WM4 HWM5) | exact Hcs].
    - rewrite (ret_pc_even OS_LO_RET ltac:(unfold OS_LO_RET; lia) eq_refl).
      assert (HX0 : r0 <> Z_to_bv 64 0).
      { rewrite Hr0. intros E. apply Hr.
        pose proof (f_equal bv_unsigned E) as E'. rewrite !Z_to_bv_unsigned in E'.
        unfold bv_wrap in E'. change (bv_modulus 64) with (2 ^ 64) in E'.
        rewrite Z.mod_0_l in E' by lia.
        pose proof (Z.div_mod r (2 ^ 64) ltac:(lia)) as Q.
        rewrite E' in Q. lia. }
      destruct (os_tail true (Z_to_bv 64 OS_LO_RET) w0 w1 w2 r0 r1 w3 w4 w5 w6 w7 w8 w9 w10 w11 w12
                  ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m4 (seg_rom asegs)
                  ff fp (bv_unsigned sp) (bv_unsigned sp - 64 - bv_unsigned sp mod 32) _
                  (conj HX0 eq_refl) G3 ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia)
                  ltac:(lia) HRW4 CFP4 WF4 WS4 WP4 HINV4)
        as (R6 & M6 & RUN6 & E6 & HMU6 & HWM6 & HINV6 & HSTK6 & HRD6).
      rewrite E6 in RUN6. rewrite !Z_to_bv_bv_unsigned in RUN6 |- *.
      eapply (os_fin ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB LF lo m m4 _ OS_LO_RET M6 ff fp _ 7);
        [exact Hsp47 | exact Hlo | exact Hlo2 | exact FFR | exact RUN6 | exact HMU6 | exact HWM6 | exact HINV6
        | exact HSTK6 | exact HRD6 | exact HRF4 | exact HRH4 | exact HAC4 | exact STK4 | exact MU4 | exact WM4
        | exact unknown_cstr].
  Qed.
End OS.
